from .commisioning_file import CommissioningBaseFile
import xml.etree.ElementTree as ET
from .utils import info


class Delta(CommissioningBaseFile):
    def __init__(self):
        super(Delta, self).__init__([])

    @info('Deleting')
    def delete(self, moc):
        deleted_moc = self._shallow_clone(moc)
        deleted_moc.set('operation', 'delete')
        self.cmdata.append(deleted_moc)

    @info('Updating')
    def update(self, moc, params):
        updated_moc = self._shallow_clone(moc)
        updated_moc.set('operation', 'update')
        updated_moc.extend(params)
        self.cmdata.append(updated_moc)

    @staticmethod
    def _shallow_clone(elem):
        return ET.Element(elem.tag, elem.attrib)
